import { Component, OnInit } from '@angular/core';
import { Company } from 'src/app/landing/models/company';
import { CompanyService } from 'src/app/service/company/company.service';

@Component({
  selector: 'app-edit-profile',
  templateUrl: './edit-profile.component.html',
  styleUrls: ['./edit-profile.component.css']
})
export class EditProfileComponent implements OnInit {

  company!: Company;

  constructor(private compService: CompanyService) {}

  ngOnInit(): void {
    this.getCompanyById();
  }

  getCompanyById() {
    this.compService.getCompanyById(Number(localStorage.getItem('id')))
      .subscribe(res => this.company = res);
  }
}
<div class="page">
<app-header variant="company"></app-header>
<div class="app-shell">
<app-sidebar variant="company"></app-sidebar>
<main class="main">

<div class="page-title">Edit Company Profile</div>
<div class="form-card">
<form ngClass="editCompanyForm" [ngS]>
  <div class="field"><label>Company name</label><input [value]="company?.companyName"></div>
  <div class="field"><label>Website</label><input [value]="company?.website"></div>
  <div class="field"><label>Location</label><input [value]="company?.location"></div>
  <div class="field"><label>Description</label><textarea>{{company?.description}}</textarea></div>
  <div class="form-actions">
    <a routerLink="/profile-company" class="btn btn-primary">Save changes</a>
    <a routerLink="/profile-company" class="btn btn-secondary">Cancel</a>
  </div>
</form>
</div>

</main>
</div>
</div>
